[tool error]
{
  "ok": false,
  "name": "create_layer",
  "error": {
    "type": "invalid_params",
    "message": "'solid' is not one of ['continuous', 'dashed', 'center', 'hidden', 'dot', 'phantom'] (at 'linetype')",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1
        },
        "color": {
          "type": "string",
          "description": "named CAD color (black, red, yellow, green, cyan, blue, magenta, gray, white) or '#RRGGBB'"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ]
        },
        "lineweight_mm": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "plotted lineweight in mm"
        },
        "description": {
          "type": "string"
        }
      },
      "required": [
        "name"
      ],
      "additionalProperties": false
    },
    "example": {
      "name": "V-ALIGN-CNTR",
      "color": "red",
      "linetype": "center",
      "lineweight_mm": 0.35,
      "description": "Roadway centerline"
    }
  },
  "warnings": []
}
